-- A received line's colour is frozen exactly like its fabric (0024 D7). Same function body as
-- 0024 (message now names fabric_color_id); the UPDATE trigger is re-created so its WHEN list
-- includes the new column. The DELETE trigger is unchanged (it calls the same function).
CREATE OR REPLACE FUNCTION prevent_received_purchase_item_change()
RETURNS trigger AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM "goods_receipt_items" gri
    JOIN "goods_receipts" gr ON gr."id" = gri."goods_receipt_id"
    WHERE gri."purchase_item_id" = OLD."id"
      AND gr."kind" = 'receipt'
      AND gr."reversed_at" IS NULL
  ) THEN
    RAISE EXCEPTION 'cannot change or delete a purchase line that already has a receipt (qty_ordered, total_amount, item_type, fabric_id, fabric_color_id, accessory_id are frozen)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
--> statement-breakpoint

DROP TRIGGER IF EXISTS prevent_received_purchase_item_change ON "purchase_items";--> statement-breakpoint

CREATE TRIGGER prevent_received_purchase_item_change BEFORE UPDATE ON "purchase_items" FOR EACH ROW
  WHEN (
    NEW.qty_ordered IS DISTINCT FROM OLD.qty_ordered OR
    NEW.total_amount IS DISTINCT FROM OLD.total_amount OR
    NEW.item_type IS DISTINCT FROM OLD.item_type OR
    NEW.fabric_id IS DISTINCT FROM OLD.fabric_id OR
    NEW.fabric_color_id IS DISTINCT FROM OLD.fabric_color_id OR
    NEW.accessory_id IS DISTINCT FROM OLD.accessory_id
  )
  EXECUTE FUNCTION prevent_received_purchase_item_change();
--> statement-breakpoint

-- A posted batch's fabric usage is history (it is what the posted fabric_stock_movements rows
-- and the frozen HPP were computed from). Copy of 0007's prevent_posted_batch_items_mutation:
-- rejects INSERT/UPDATE/DELETE while the parent batch is posted; a draft's rows stay freely
-- replaceable, and deleting a draft cascades through here (status 'draft' passes). Unlike the
-- 0007 original it checks BOTH sides of an UPDATE, so a posted batch's row cannot be moved onto a
-- draft (OLD side) and a draft's row cannot be moved onto a posted batch (NEW side).
CREATE OR REPLACE FUNCTION prevent_posted_batch_fabric_usage_mutation()
RETURNS trigger AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM "production_batches"
    WHERE status = 'posted'
      AND id IN (
        CASE WHEN TG_OP <> 'INSERT' THEN OLD.production_batch_id END,
        CASE WHEN TG_OP <> 'DELETE' THEN NEW.production_batch_id END
      )
  ) THEN
    RAISE EXCEPTION 'cannot modify fabric usage of a posted production batch' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
--> statement-breakpoint

DROP TRIGGER IF EXISTS prevent_posted_batch_fabric_usage_mutation ON "production_batch_fabric_usages";--> statement-breakpoint

CREATE TRIGGER prevent_posted_batch_fabric_usage_mutation BEFORE INSERT OR UPDATE OR DELETE ON "production_batch_fabric_usages"
  FOR EACH ROW EXECUTE FUNCTION prevent_posted_batch_fabric_usage_mutation();
